def _append_lines(text, extra):
    lines = [l for l in text.splitlines() if l.strip()]
    lower = {l.strip().lower() for l in lines}
    lines += [e for e in extra if e.lower() not in lower]
    return "\n".join(lines)


def expand(apps, schema_editor):
    Market = apps.get_model("agent", "Market")
    AgentConfig = apps.get_model("agent", "AgentConfig")
    start = (Market.objects.order_by("-sort").values_list("sort", flat=True).first() or 0) + 1
    for i, (name, enabled, currency, code, tz, lang, postal, note, cities) in enumerate(NEW_MARKETS):
        Market.objects.get_or_create(name=name, defaults=dict(
            enabled=enabled, currency=currency, calling_code=code, timezone=tz, language=lang,
            requires_postal_address=postal, rules_note=note, cities="\n".join(cities), sort=start + i,
        ))
    Market.objects.filter(name__in=ENABLE).update(enabled=True)
    for name, cities in MORE_CITIES.items():
        for market in Market.objects.filter(name=name):
            market.cities = _append_lines(market.cities, cities)
            market.save(update_fields=["cities"])
    for config in AgentConfig.objects.all():
        config.target_categories = _append_lines(config.target_categories, MORE_SECTORS)
        config.gig_subreddits = _append_lines(config.gig_subreddits, MORE_SUBREDDITS)
        config.save(update_fields=["target_categories", "gig_subreddits"])


